#!/bin/sh
python3 - <<'PY'
import base64,csv,gzip,hashlib,json,signal,sys,time,types
from pathlib import Path
sys.path.insert(0,'/opt/sccc-building-diagnostics/current')
raw=gzip.decompress(base64.b64decode(''))
module=types.ModuleType('sccc_fdb_bulk_candidate')
exec(compile(raw,'sccc_fdb_bulk_candidate','exec'),module.__dict__)
def stop(*_): raise TimeoutError('bounded one-target candidate deadline')
signal.signal(signal.SIGALRM,stop);signal.alarm(90)
agent=module.load_agent(Path('/opt/sccc-noc-probe/noc_probe_agent.py'))
rows=list(csv.DictReader(Path('/etc/sccc-building-diagnostics/targets.csv').open()))
target=next(row for row in rows if row['ip']=='192.168.2.27')
started=time.monotonic()
try:
 result=module.collect_one({'hostname':target['name'],'ip':target['ip'],'building':target['building']},agent,{},Path('/proc/sys/kernel/random/boot_id').read_text().strip(),{r['name'].lower() for r in rows})
 print(json.dumps({'candidateSha256':hashlib.sha256(raw).hexdigest(),'name':target['name'],'seconds':round(time.monotonic()-started,3),'ok':result['ok'],'observations':len(result['observations']),'eligibleAccessPorts':len(result['ports']),'counterPortStates':len(result['counters']),'pilotMacMatches':sum(r['mac']=='ac:b4:80:0b:98:c3' for r in result['observations'])},separators=(',',':')))
except Exception as error:
 print(json.dumps({'name':target['name'],'seconds':round(time.monotonic()-started,3),'failureClass':type(error).__name__},separators=(',',':')))
signal.alarm(0)
PY